%% validate_dataset.m
%
% Reads and validates the patch dataset generated by gen_dataset_from_dem.m.
%
% What it checks
% ──────────────
%   1. Directory inventory   – counts .mat files in every expected sub-folder.
%   2. Patch count balance   – warns if counts differ across types.
%   3. Per-patch inspection  – for a random sample of patches verifies:
%        • size  == [patch_size × patch_size]
%        • value range (wrapped ∈ [−π,π], real/imag ∈ [−1,1],
%                       coherence ∈ [0,1], wrap_count ≥ 0)
%        • cross-type consistency
%            real(exp(i·w))  ≈  wrapped_real
%            imag(exp(i·w))  ≈  wrapped_imag
%            real² + imag²   ≈  1
%   4. Log file summary      – prints stats from the latest CSV logs.
%   5. Visualisation         – when n_sample < Inf, shows one imagesc figure
%                              per sampled patch (all available data types).
%
% Usage
% ─────
%   Run this script from within MATLAB after running gen_dataset_from_dem.m.
%   Adjust the USER CONFIGURATION section below if needed.
%
% -------------------------------------------------------------------------
clc; clear; close all;

%% ══════════════════════════════════════════════════════════════════════════
%  USER CONFIGURATION
%  ══════════════════════════════════════════════════════════════════════════

% Root of the patches output (must match gen_dataset_from_dem.m)
script_dir    = fileparts(mfilename('fullpath'));  % dem2phase/scripts/
dem2phase_dir = fileparts(script_dir);            % dem2phase/
repo_root     = fileparts(dem2phase_dir);         % repo root
output_root   = fullfile(repo_root, 'data', 'patches');

% Number of randomly sampled patches for detailed per-patch checks.
% Set to Inf to check every patch (slow for large datasets).
n_sample = inf;

% Patch size expected in every saved file
patch_size = 256;

% Tolerance for floating-point consistency checks
tol = 1e-6;

%% ══════════════════════════════════════════════════════════════════════════
%  END USER CONFIGURATION
%  ══════════════════════════════════════════════════════════════════════════

% Mapping: logical type → sub-folder name  (mirrors gen_dataset_from_dem.m)
SUBDIRS = struct( ...
    'wrapped_phase',                'wrappedphase_withoutnoise', ...
    'wrapped_phase_real',           'wrappedphase_withoutnoise_real', ...
    'wrapped_phase_imag',           'wrappedphase_withoutnoise_imag', ...
    'wrapped_phase_withnoise',      'wrappedphase_withnoise', ...
    'wrapped_phase_withnoise_real', 'wrappedphase_withnoise_real', ...
    'wrapped_phase_withnoise_imag', 'wrappedphase_withnoise_imag', ...
    'unwrapped_phase',              'unwrapped_phase', ...
    'wrap_count',                   'wrapped_number', ...
    'coherence_estimated',          'coherence_estimated');

type_names = fieldnames(SUBDIRS);

total_errors   = 0;
total_warnings = 0;

fprintf('\n');
fprintf('╔══════════════════════════════════════════════════════════════╗\n');
fprintf('║            validate_dataset  –  dataset QA report           ║\n');
fprintf('╚══════════════════════════════════════════════════════════════╝\n');
fprintf(' Output root : %s\n\n', output_root);

%% ── 1.  Directory existence & file inventory ─────────────────────────────
fprintf('──────────────────────────────────────\n');
fprintf(' [1] Directory inventory\n');
fprintf('──────────────────────────────────────\n');

if ~exist(output_root, 'dir')
    fprintf('[ERROR] Output root does not exist: %s\n', output_root);
    fprintf('        Run gen_dataset_from_dem.m first.\n');
    return
end

counts = struct();
for ti = 1:numel(type_names)
    tname  = type_names{ti};
    subdir = SUBDIRS.(tname);
    dpath  = fullfile(output_root, subdir);
    if ~exist(dpath, 'dir')
        fprintf('  [MISSING] %-35s  ->  %s\n', subdir, dpath);
        counts.(tname) = 0;
        total_warnings = total_warnings + 1;
    else
        mats = dir(fullfile(dpath, '*.mat'));
        counts.(tname) = numel(mats);
        fprintf('  %-35s  %5d .mat files\n', subdir, numel(mats));
    end
end
fprintf('\n');

%% ── 2.  Patch count balance ──────────────────────────────────────────────
fprintf('──────────────────────────────────────\n');
fprintf(' [2] Patch count balance\n');
fprintf('──────────────────────────────────────\n');

all_counts = struct2array(counts);
present    = all_counts(all_counts > 0);

if isempty(present)
    fprintf('[ERROR] No .mat files found in any sub-folder.\n');
    total_errors = total_errors + 1;
else
    ref_count = max(all_counts);  % expected count = folder with most files
    ok = true;
    for ti = 1:numel(type_names)
        tname = type_names{ti};
        c     = counts.(tname);
        if c > 0 && c ~= ref_count
            fprintf('  [WARN] %-35s  has %d files (expected %d)\n', ...
                SUBDIRS.(tname), c, ref_count);
            total_warnings = total_warnings + 1;
            ok = false;
        end
    end
    if ok
        fprintf('  All present types agree: %d patches each.\n', ref_count);
    end
end
fprintf('\n');

%% ── 3.  Per-patch detailed checks ────────────────────────────────────────
fprintf('──────────────────────────────────────\n');
fprintf(' [3] Per-patch checks  (sample = %d)\n', n_sample);
fprintf('──────────────────────────────────────\n');

% Use wrapped_phase folder as the reference source for patch names
ref_dir = fullfile(output_root, SUBDIRS.wrapped_phase);
if ~exist(ref_dir, 'dir') || counts.wrapped_phase == 0
    fprintf('  [SKIP] wrapped_phase folder empty – cannot run per-patch checks.\n\n');
else
    ref_mats  = dir(fullfile(ref_dir, '*.mat'));
    n_total   = numel(ref_mats);
    n_check   = min(n_sample, n_total);
    idx_check = sort(randperm(n_total, n_check));

    patch_errors   = 0;
    patch_warnings = 0;

    for ii = 1:n_check
        mat_name   = ref_mats(idx_check(ii)).name;
        patch_stem = regexprep(mat_name, '_wrapped_phase\.mat$', '');
        errs       = {};

        % ── Load all available types ─────────────────────────────────────
        d = struct();
        for ti = 1:numel(type_names)
            tname = type_names{ti};
            % Reconstruct expected filename for this type
            fpath = fullfile(output_root, SUBDIRS.(tname), ...
                [patch_stem '_' strrep(tname,'_withoutnoise','') '.mat']);
            % Exact filename = patch_stem + '_' + type_suffix + '.mat'
            % (gen_dataset_from_dem saves as sprintf('%s_%s.mat', patch_name, patch_type))
            fpath2 = fullfile(output_root, SUBDIRS.(tname), ...
                sprintf('%s_%s.mat', patch_stem, tname));
            if exist(fpath2, 'file')
                s = load(fpath2, 'data');
                d.(tname) = s.data;
            elseif exist(fpath, 'file')
                s = load(fpath, 'data');
                d.(tname) = s.data;
            end
        end

        % ── Size check ───────────────────────────────────────────────────
        loaded_types = fieldnames(d);
        for li = 1:numel(loaded_types)
            lname = loaded_types{li};
            sz = size(d.(lname));
            if ~isequal(sz, [patch_size patch_size])
                errs{end+1} = sprintf('%s: size %dx%d (expected %dx%d)', ...
                    lname, sz(1), sz(2), patch_size, patch_size); %#ok<AGROW>
            end
        end

        % ── Value range checks ────────────────────────────────────────────
        if isfield(d, 'wrapped_phase')
            wp = d.wrapped_phase;
            if min(wp(:)) < -pi - tol || max(wp(:)) > pi + tol
                errs{end+1} = sprintf('wrapped_phase out of [-pi,pi]: [%.4f, %.4f]', ...
                    min(wp(:)), max(wp(:)));
            end
        end

        for tname_ri = {'wrapped_phase_real', 'wrapped_phase_imag', ...
                        'wrapped_phase_withnoise_real', 'wrapped_phase_withnoise_imag'}
            tname_r = tname_ri{1};
            if isfield(d, tname_r)
                v = d.(tname_r);
                if min(v(:)) < -1 - tol || max(v(:)) > 1 + tol
                    errs{end+1} = sprintf('%s out of [-1,1]: [%.4f, %.4f]', ...
                        tname_r, min(v(:)), max(v(:))); %#ok<AGROW>
                end
            end
        end

        if isfield(d, 'wrapped_phase_withnoise')
            wn = d.wrapped_phase_withnoise;
            if min(wn(:)) < -pi - tol || max(wn(:)) > pi + tol
                errs{end+1} = sprintf('wrapped_phase_withnoise out of [-pi,pi]: [%.4f, %.4f]', ...
                    min(wn(:)), max(wn(:))); %#ok<AGROW>
            end
        end

        if isfield(d, 'coherence_estimated')
            ce = d.coherence_estimated;
            if min(ce(:)) < -tol || max(ce(:)) > 1 + tol
                errs{end+1} = sprintf('coherence_estimated out of [0,1]: [%.4f, %.4f]', ...
                    min(ce(:)), max(ce(:))); %#ok<AGROW>
            end
        end

        if isfield(d, 'wrap_count')
            wc = d.wrap_count;
            if any(wc(:) < 0)
                errs{end+1} = 'wrap_count contains negative values';
            end
        end

        % ── Cross-type consistency ────────────────────────────────────────
        if isfield(d, 'wrapped_phase') && isfield(d, 'wrapped_phase_real')
            expected_r = real(exp(1i * d.wrapped_phase));
            err_r = max(abs(d.wrapped_phase_real(:) - expected_r(:)));
            if err_r > 1e-4
                errs{end+1} = sprintf('wrapped_real vs angle mismatch: max_err=%.2e', err_r);
            end
        end

        if isfield(d, 'wrapped_phase') && isfield(d, 'wrapped_phase_imag')
            expected_i = imag(exp(1i * d.wrapped_phase));
            err_i = max(abs(d.wrapped_phase_imag(:) - expected_i(:)));
            if err_i > 1e-4
                errs{end+1} = sprintf('wrapped_imag vs angle mismatch: max_err=%.2e', err_i);
            end
        end

        if isfield(d, 'wrapped_phase_real') && isfield(d, 'wrapped_phase_imag')
            unit_err = max(abs(d.wrapped_phase_real(:).^2 + ...
                              d.wrapped_phase_imag(:).^2 - 1));
            if unit_err > 1e-4
                errs{end+1} = sprintf('real^2+imag^2 != 1: max_err=%.2e', unit_err);
            end
        end

        % ── Report ────────────────────────────────────────────────────────
        if isempty(errs)
            status = 'OK';
        else
            status = 'FAIL';
            patch_errors = patch_errors + numel(errs);
        end
        fprintf('  [%s] %s\n', status, patch_stem);
        for ei = 1:numel(errs)
            fprintf('        ✗ %s\n', errs{ei});
        end

        % ── Visualise (only when n_sample is finite) ──────────────────────
        if ~isinf(n_sample)
            % Fixed display order with human-readable titles
            vis_order = { ...
                'wrapped_phase',                'Wrapped phase (clean)'; ...
                'wrapped_phase_withnoise',      'Wrapped phase (noisy)'; ...
                'unwrapped_phase',              'Unwrapped phase (DEM×ratio)'; ...
                'wrapped_phase_real',           'Real part – clean'; ...
                'wrapped_phase_imag',           'Imag part – clean'; ...
                'wrapped_phase_withnoise_real', 'Real part – noisy'; ...
                'wrapped_phase_withnoise_imag', 'Imag part – noisy'; ...
                'wrap_count',                   'Wrap count'; ...
                'coherence_estimated',          'Coherence (estimated)'};

            % Keep only types that were actually loaded
            mask = cellfun(@(t) isfield(d, t), vis_order(:,1));
            vis_order = vis_order(mask, :);
            n_vis = size(vis_order, 1);

            if n_vis > 0
                n_cols = min(n_vis, 3);
                n_rows = ceil(n_vis / n_cols);

                fig = figure('Name', patch_stem, ...
                             'NumberTitle', 'off', ...
                             'Units', 'normalized', ...
                             'Position', [0.05, 0.05, 0.9, min(0.9, 0.30*n_rows)]);

                for vi = 1:n_vis
                    subplot(n_rows, n_cols, vi);
                    imagesc(d.(vis_order{vi,1}));
                    axis image off;
                    colorbar;
                    title(vis_order{vi,2}, 'Interpreter', 'none', 'FontSize', 8);
                end

                sgtitle(strrep(patch_stem, '_', '\_'), 'FontSize', 9, 'FontWeight', 'bold');
                drawnow;
            end
        end
    end

    total_errors   = total_errors   + patch_errors;
    total_warnings = total_warnings + patch_warnings;

    fprintf('\n  Checked %d / %d patches.  Errors: %d\n', ...
        n_check, n_total, patch_errors);
end
fprintf('\n');

%% ── 4.  Log file summary ─────────────────────────────────────────────────
fprintf('──────────────────────────────────────\n');
fprintf(' [4] Log file summary\n');
fprintf('──────────────────────────────────────\n');

log_files = dir(fullfile(output_root, 'generation_log_*.csv'));
if isempty(log_files)
    fprintf('  No generation_log_*.csv found – skipping.\n');
else
    % Use the most recent log
    [~, newest_idx] = max([log_files.datenum]);
    log_path = fullfile(output_root, log_files(newest_idx).name);
    fprintf('  Log : %s\n', log_path);

    try
        T = readtable(log_path);
        fprintf('  Source DEM files processed : %d\n', height(T));
        fprintf('  Total patches saved        : %d\n', sum(T.patches_saved));
        fprintf('  Total attempts             : %d\n', sum(T.attempts_total));
        fprintf('  Total wrap-skipped         : %d\n', sum(T.wrap_skipped));
        fprintf('  Total void-skipped         : %d\n', sum(T.void_skipped));
        fprintf('  Total elapsed (s)          : %.1f\n', sum(T.elapsed_s));
        fprintf('  RNG seed used              : %s\n', ...
            num2str(unique(T.rng_seed)));

        if any(T.patches_saved == 0)
            zero_files = T.source_file(T.patches_saved == 0);
            fprintf('  [WARN] %d source file(s) produced zero patches:\n', ...
                sum(T.patches_saved == 0));
            for zi = 1:numel(zero_files)
                fprintf('         %s\n', zero_files{zi});
            end
            total_warnings = total_warnings + 1;
        end
    catch ME
        fprintf('  [WARN] Could not parse log: %s\n', ME.message);
        total_warnings = total_warnings + 1;
    end
end

%% ── 5.  Detail log quick stats ───────────────────────────────────────────
detail_files = dir(fullfile(output_root, 'generation_detail_*.csv'));
if ~isempty(detail_files)
    [~, newest_idx] = max([detail_files.datenum]);
    detail_path = fullfile(output_root, detail_files(newest_idx).name);
    fprintf('\n  Detail log : %s\n', detail_path);
    try
        D = readtable(detail_path);
        fprintf('  Patch rows in detail log   : %d\n', height(D));
        fprintf('  max_wrap_count   min/mean/max : %.0f / %.2f / %.0f\n', ...
            min(D.max_wrap_count), mean(D.max_wrap_count), max(D.max_wrap_count));
        fprintf('  coh_input_mean   min/mean/max : %.3f / %.3f / %.3f\n', ...
            min(D.coh_input_mean), mean(D.coh_input_mean), max(D.coh_input_mean));
        fprintf('  coh_estimated_mean min/mean/max : %.3f / %.3f / %.3f\n', ...
            min(D.coh_estimated_mean), mean(D.coh_estimated_mean), ...
            max(D.coh_estimated_mean));
        fprintf('  interp_scale     min/mean/max : %.2f / %.2f / %.2f\n', ...
            min(D.interp_scale), mean(D.interp_scale), max(D.interp_scale));
    catch ME
        fprintf('  [WARN] Could not parse detail log: %s\n', ME.message);
    end
end
fprintf('\n');

%% ── 6.  Final verdict ────────────────────────────────────────────────────
fprintf('══════════════════════════════════════\n');
if total_errors == 0 && total_warnings == 0
    fprintf('  ✔  All checks passed.\n');
elseif total_errors == 0
    fprintf('  ⚠  Passed with %d warning(s).\n', total_warnings);
else
    fprintf('  ✘  %d error(s),  %d warning(s) found.\n', ...
        total_errors, total_warnings);
end
fprintf('══════════════════════════════════════\n\n');
